/// <summary>
///
/// </summary>
public static TFMDeltaPages Find(QueryName _queryName, boolean _selectForUpdate = false)
{
    TFMDeltaPages   pages;
    Name            name;

    pages.selectForUpdate(_selectForUpdate);

    select firstonly pages where pages.QueryName == _queryName;
    if (pages)
    {
        return pages;
    }
    name  =_queryName;
    select firstonly pages where pages.Name == name;

    return pages;
}

/// <summary>
/// Gets all page ids/ page names that has been overridden.
/// </summary>
/// <returns>Set of page ids/names</returns>
public static Set GetAllPageNames()
{
    TFMDeltaPages pages;
    Set pagesSet = new Set(Types::String);

    pages.selectForUpdate(false);
    while select pages 
    {
        if(pages.QueryName)
        {
            pagesSet.add(pages.QueryName);
        }
        else if(pages.Name)
        {
            pagesSet.add(pages.Name);
        }
    }
    return pagesSet;
}

    public static void createFromPageClass(TFMPage _page, boolean _includeParams = false)
    {
        TFMDeltaPages   queryPage = TFMDeltaPages::Find(_page.parmId(), true);

        queryPage.Name = _page.parmId();
        queryPage.FilterName = _page.parmFilter();
        queryPage.Type  = (_page.parmType()) ? _page.parmType() : queryPage.Name;
        queryPage.Icon  = _page.parmIcon();
        queryPage.Title = _page.parmTitle();
        queryPage.write();

		//Save individual Values that are different from their default.
        if(_includeParams)
        {
            _page.saveAllParms();
        }

		// Initialize default Actions
        TFMDeltaPages::addAllmandatoryActions(queryPage);
    }

    public static void addAllmandatoryActions(TFMDeltaPages   _pages)
    {
        TFMPageActions		actions;
        ListEnumerator		allClasses = new SysDictClass(classNum(TFMDocumentHandler)).extendedBy(true).getEnumerator();
        SysDictClass		dc;
        TFMDocumentHandler	dh;
        MapEnumerator		mEnum;
        TFMPage				page;

		while (allClasses.moveNext())
        {
            dc = new SysDictClass(allClasses.current());
			if (!dc || dc.isAbstract())
            {
                continue;
            }
            dh = dc.makeObject();
            mEnum = dh.pages().getPages().getEnumerator();
			while (mEnum.moveNext())
            {
                page = mEnum.currentValue();
				if (page.parmIsMandatoryContextMenu() && page.parmId() != _pages.Name)
                {
                    actions.Name = _pages.Name;
                    actions.Id = page.parmId();
                    actions.Icon = page.parmIcon();
                    actions.Title=page.parmTitle();
                    actions.insert();
                }
            }
		}
    }
